// create a cache for fast id lookup
static unsigned short *make_id2insn(const insn_map *insns, unsigned int size)
{
        // NOTE: assume that the max id is always put at the end of insns array
        unsigned short max_id = insns[size - 1].id;
        unsigned short i;

        unsigned short *cache = (unsigned short *)cs_mem_calloc(max_id + 1, sizeof(*cache));

        for (i = 1; i < size; i++)
                cache[insns[i].id] = i;

        return cache;
}

// look for @id in @insns, given its size in @max. first time call will update @cache.
// return 0 if not found
unsigned short insn_find(const insn_map *insns, unsigned int max, unsigned int id, unsigned short **cache)
{
        if (id > insns[max - 1].id)
                return 0;

        if (*cache == NULL)
                *cache = make_id2insn(insns, max);

        return (*cache)[id];
}

int name2id(const name_map* map, int max, const char *name)
{
        int i;

        for (i = 0; i < max; i++) {
                if (!strcmp(map[i].name, name)) {
                        return map[i].id;
                }
        }

        // nothing match
        return -1;
}

const char *id2name(const name_map* map, int max, const unsigned int id)
{
        int i;

        for (i = 0; i < max; i++) {
                if (map[i].id == id) {
                        return map[i].name;
                }
        }

        // nothing match
        return NULL;
}

// count number of positive members in a list.
// NOTE: list must be guaranteed to end in 0
unsigned int count_positive(const uint16_t *list)
{
        unsigned int c;

        for (c = 0; list[c] > 0; c++);

        return c;
}

// count number of positive members in a list.
